const genId = (): string => {
  if (typeof (globalThis as any).crypto?.randomUUID === "function") return (globalThis as any).crypto.randomUUID();
  // fallback to pseudo UUID
  return "u-" + Math.random().toString(36).slice(2, 10);
};

