import { INotificationService, Notification, TaskAssignedPayload, TaskStatusChangedPayload, CommentAddedPayload } from "../types";
import { EventBus } from "../event-bus";

const genId = (): string => {
  if (typeof (globalThis as any).crypto?.randomUUID === "function") return (globalThis as any).crypto.randomUUID();
  return "n-" + Math.random().toString(36).slice(2, 10);
};

export class NotificationService implements INotificationService {
  private store: Map<string, Notification> = new Map();
  private bus: EventBus;

  constructor(bus: EventBus) {
    this.bus = bus;

    this.bus.subscribe("task.assigned", (payload) => {
      const p = payload as TaskAssignedPayload;
      const msg = `Task '${p.taskTitle}' assigned to you`;
      const n: Notification = { id: genId(), userId: p.assigneeId, message: msg, read: false, createdAt: new Date().toISOString() };
      this.store.set(n.id, n);
    });

    this.bus.subscribe("task.statusChanged", (payload) => {
      const p = payload as TaskStatusChangedPayload;
      if (!p.assigneeId) return;
      const msg = `Task '${p.taskTitle}' status changed to ${p.newStatus}`;
      const n: Notification = { id: genId(), userId: p.assigneeId, message: msg, read: false, createdAt: new Date().toISOString() };
      this.store.set(n.id, n);
    });

    this.bus.subscribe("comment.added", (payload) => {
      const p = payload as CommentAddedPayload;
      // We expect main to have enriched payload with assigneeId and authorName/taskTitle maybe; but spec: creates notification for task assignee about new comment
      // If payload doesn't include assigneeId, ignore
      const anyp = payload as any;
      if (!anyp.assigneeId) return;
      const msg = `New comment on task '${anyp.taskTitle}' by ${anyp.authorName}`;
      const n: Notification = { id: genId(), userId: anyp.assigneeId, message: msg, read: false, createdAt: new Date().toISOString() };
      this.store.set(n.id, n);
    });
  }

  getByUser(userId: string): Notification[] {
    return Array.from(this.store.values()).filter((n) => n.userId === userId).sort((a, b) => a.createdAt.localeCompare(b.createdAt));
  }

  markAsRead(notificationId: string): Notification {
    const n = this.store.get(notificationId);
    if (!n) throw new Error("Notification not found");
    n.read = true;
    this.store.set(notificationId, n);
    return n;
  }
}

import { createServer, IncomingMessage, ServerResponse } from "http";
import { EventBus } from "./event-bus";
import { UserService } from "./services/user-service";
import { ProjectService } from "./services/project-service";
import { TaskService } from "./services/task-service";
import { CommentService } from "./services/comment-service";
import { NotificationService } from "./services/notification-service";
import { parse as parseUrl } from "url";

function json(res: ServerResponse, status: number, data: unknown) {
  res.writeHead(status, { "Content-Type": "application/json" });
  res.end(JSON.stringify(data));
}

function parseBody(req: IncomingMessage): Promise<any> {
  return new Promise((resolve, reject) => {
    const chunks: Buffer[] = [];
    req.on("data", (c) => chunks.push(Buffer.from(c)));
    req.on("end", () => {
      if (chunks.length === 0) return resolve({});
      try {
        const s = Buffer.concat(chunks).toString();
        resolve(s ? JSON.parse(s) : {});
      } catch (e) {
        reject(e);
      }
    });
    req.on("error", reject);
  });
}

export function createRouter() {
  const bus = new EventBus();
  const userService = new UserService();
  const projectService = new ProjectService();
  const taskService = new TaskService(bus);
  const commentService = new CommentService(bus);
  const notificationService = new NotificationService(bus);

  // Enrich comment.added events with task title, assigneeId and authorName by subscribing here
  bus.subscribe("comment.added", (payload) => {
    const p: any = payload || {};
    try {
      const commentId = p.commentId;
      const task = taskService.getById(p.taskId);
      const author = userService.getById(p.authorId);
      const enriched = { ...p, taskTitle: task.title, authorName: author.name, assigneeId: task.assigneeId };
      // re-publish enriched payload to same event so notification service can consume enriched
      bus.publish("comment.added", enriched);
    } catch (e) {
      // ignore enrichment failures
    }
  });

  const server = createServer(async (req, res) => {
    const url = parseUrl(req.url || "", true);
    const method = req.method || "GET";

    try {
      // USERS
      if (url.pathname === "/users" && method === "GET") return json(res, 200, userService.getAll());
      if (url.pathname === "/users" && method === "POST") {
        const body = await parseBody(req);
        const u = userService.create(body);
        return json(res, 201, u);
      }
      if (url.pathname && url.pathname.startsWith("/users/") && method === "GET") {
        const id = url.pathname.split("/")[2];
        return json(res, 200, userService.getById(id));
      }
      if (url.pathname && url.pathname.startsWith("/users/") && method === "PUT") {
        const id = url.pathname.split("/")[2];
        const body = await parseBody(req);
        return json(res, 200, userService.update(id, body));
      }
      if (url.pathname && url.pathname.startsWith("/users/") && method === "DELETE") {
        const id = url.pathname.split("/")[2];
        userService.delete(id);
        return json(res, 204, {});
      }

      // PROJECTS
      if (url.pathname === "/projects" && method === "GET") return json(res, 200, projectService.getAll());
      if (url.pathname === "/projects" && method === "POST") {
        const body = await parseBody(req);
        const p = projectService.create(body);
        return json(res, 201, p);
      }
      if (url.pathname && url.pathname.startsWith("/projects/") && method === "GET") {
        const id = url.pathname.split("/")[2];
        return json(res, 200, projectService.getById(id));
      }
      if (url.pathname && url.pathname.startsWith("/projects/") && method === "PUT") {
        const id = url.pathname.split("/")[2];
        const body = await parseBody(req);
        return json(res, 200, projectService.update(id, body));
      }
      if (url.pathname && url.pathname.startsWith("/projects/") && method === "DELETE") {
        const id = url.pathname.split("/")[2];
        projectService.delete(id);
        return json(res, 204, {});
      }
      if (url.pathname && url.pathname.match(/^\/projects\/[^\/]+\/members$/) && method === "POST") {
        const id = url.pathname.split("/")[2];
        const body = await parseBody(req);
        return json(res, 200, projectService.addMember(id, body.userId));
      }
      if (url.pathname && url.pathname.match(/^\/projects\/[^\/]+\/members$/) && method === "DELETE") {
        const id = url.pathname.split("/")[2];
        const body = await parseBody(req);
        return json(res, 200, projectService.removeMember(id, body.userId));
      }

      // TASKS
      if (url.pathname === "/tasks" && method === "GET") {
        const projectId = (url.query as any).projectId;
        if (!projectId) return json(res, 400, { error: "projectId required" });
        return json(res, 200, taskService.getByProject(projectId));
      }
      if (url.pathname === "/tasks" && method === "POST") {
        const body = await parseBody(req);
        const t = taskService.create(body);
        return json(res, 201, t);
      }
      if (url.pathname && url.pathname.startsWith("/tasks/") && method === "GET") {
        const id = url.pathname.split("/")[2];
        return json(res, 200, taskService.getById(id));
      }
      if (url.pathname && url.pathname.startsWith("/tasks/") && method === "PUT") {
        const parts = url.pathname.split("/");
        const id = parts[2];
        if (parts[3] === "status") {
          const body = await parseBody(req);
          return json(res, 200, taskService.changeStatus(id, body.status));
        } else if (parts[3] === "assign") {
          const body = await parseBody(req);
          return json(res, 200, taskService.assign(id, body.assigneeId));
        } else {
          const body = await parseBody(req);
          return json(res, 200, taskService.update(id, body));
        }
      }
      if (url.pathname && url.pathname.startsWith("/tasks/") && method === "DELETE") {
        const id = url.pathname.split("/")[2];
        taskService.delete(id);
        return json(res, 204, {});
      }

      // COMMENTS
      if (url.pathname === "/comments" && method === "GET") {
        const taskId = (url.query as any).taskId;
        if (!taskId) return json(res, 400, { error: "taskId required" });
        return json(res, 200, commentService.getByTask(taskId));
      }
      if (url.pathname === "/comments" && method === "POST") {
        const body = await parseBody(req);
        const c = commentService.create(body);
        return json(res, 201, c);
      }
      if (url.pathname && url.pathname.startsWith("/comments/") && method === "GET") {
        const id = url.pathname.split("/")[2];
        return json(res, 200, commentService.getById(id));
      }
      if (url.pathname && url.pathname.startsWith("/comments/") && method === "DELETE") {
        const id = url.pathname.split("/")[2];
        commentService.delete(id);
        return json(res, 204, {});
      }

      // NOTIFICATIONS
      if (url.pathname === "/notifications" && method === "GET") {
        const userId = (url.query as any).userId;
        if (!userId) return json(res, 400, { error: "userId required" });
        return json(res, 200, notificationService.getByUser(userId));
      }
      if (url.pathname && url.pathname.match(/^\/notifications\/[^\/]+\/read$/) && method === "PUT") {
        const id = url.pathname.split("/")[2];
        return json(res, 200, notificationService.markAsRead(id));
      }

      json(res, 404, { error: "Not found" });
    } catch (e: any) {
      json(res, 400, { error: e.message || String(e) });
    }
  });

  return server;
}

